```python
class Stack:
    def __init__(self):
        self.items = []

    def push(self, item):
        self.items.append(item)

    def pop(self):
        if not self.is_empty():
            return self.items.pop()

    def peek(self):
        if not self.is_empty():
            return self.items[-1]

    def is_empty(self):
        return len(self.items) == 0

    def size(self):
        return len(self.items)

    def reverse(self):
        # Create an empty stack to store the reversed elements
        reversed_stack = Stack()

        # Pop elements from the original stack and push them to the reversed stack
        while not self.is_empty():
            reversed_stack.push(self.pop())

        # Copy the reversed stack back to the original stack
        self.items = reversed_stack.items


# Example usage
stack = Stack()
stack.push(1)
stack.push(2)
stack.push(3)
stack.push(4)

print("Original stack:")
while not stack.is_empty():
    print(stack.pop(), end=" ")

stack.reverse()

print("\nReversed stack:")
while not stack.is_empty():
    print(stack.pop(), end=" ")
```

This code defines a `Stack` class with methods to push, pop, peek, check if empty, get the size, and reverse the stack. The `reverse` method uses a temporary stack to store the reversed elements and then copies them back to the original stack. This approach avoids recursion and has a time complexity of O(n), where n is the number of elements in the stack.

