def add_numbers(n):
    """
    Recursive function to add numbers from 0 to n.

    Args:
        n (int): The upper limit of the range to add.

    Returns:
        int: The sum of all integers from 0 to n.

    Raises:
        ValueError: If n is less than 0.
    """
    if n < 0:
        raise ValueError("n must be a non-negative integer.")

    if n == 0:
        return 0
    else:
